    return tuple(sorted(w for w in t.split() if len(w)>3))
g=defaultdict(list)
for i in d['items']:
    g[key(i.get('title'))].append(i)
for k,v in g.items():
    if len(v)>1 and k:
        print('--- possible duplicate title group:')
        for i in v: print(f\"    {i['id']:60} {i['status']:9} owner={i.get('owner') or '-'}\")
# also: rows whose id basename repeats
bn=defaultdict(list)
for i in d['items']:
    bn[i['id'].split('.')[-1]].append(i)
print()
print('=== repeated leaf-name across cones (name, count, statuses) ===')
for k,v in sorted(bn.items()):
    if len(v)>1:
        print(f'  {k:26}', [(i[\"id\"].split(\".\")[0], i[\"status\"], i.get(\"owner\") or \"-\") for i in v])
